\n// path: test/fitur/event/page/detail_event_a_test.dart\nimport 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:flutter_test/flutter_test.dart';\nimport 'package:mockito/mockito.dart';\nimport 'package:wifi/fitur/event/model/event_model.dart';\nimport 'package:wifi/fitur/event/operasi/event_op_supabase.dart';\nimport 'package:wifi/fitur/event/page/detail_event_a.dart';\n\nclass MockEventOpSupabase extends Mock implements EventOpSupabase {}\n\nvoid main() {\n  group('DetailEventA', () {\n    late ProviderContainer container;\n    late MockEventOpSupabase mockEventOpSupabase;\n\n    final event = EventModel(\n      id: '1',\n      linkGambar: 'https://example.com/image.png',\n      statusAktif: true,\n      tanggalDibuat: DateTime.now(),\n      tanggalMulai: DateTime.now(),\n      tanggalBerakhir: DateTime.now().add(const Duration(days: 1)),\n    );\n\n    setUp(() {\n      mockEventOpSupabase = MockEventOpSupabase();\n      container = ProviderContainer(\n        overrides: [\n          eventOpSupabaseProvider.overrideWithValue(mockEventOpSupabase),\n        ],\n      );\n    });\n\n    tearDown(() {\n      container.dispose();\n    });\n\n    Future<void> pumpWidget(WidgetTester tester) async {\n      await tester.pumpWidget(\n        UncontrolledProviderScope(\n          container: container,\n          child: MaterialApp(\n            home: DetailEventA(event: event),\n          ),\n        ),\n      );\n    }\n\n    testWidgets('01. Menampilkan CircularProgressIndicator saat loading', (tester) async {\n      when(mockEventOpSupabase.ambilBerdasarkanId(any))\n          .thenAnswer((_) async => Future.delayed(const Duration(seconds: 1)));\n\n      await pumpWidget(tester);\n      expect(find.byType(CircularProgressIndicator), findsOneWidget);\n      await tester.pumpAndSettle();\n    });\n\n    testWidgets('02. Menampilkan pesan error saat terjadi kesalahan', (tester) async {\n      when(mockEventOpSupabase.ambilBerdasarkanId(any))\n          .thenThrow(Exception('Gagal memuat data'));\n\n      await pumpWidget(tester);\n      await tester.pumpAndSettle();\n\n      expect(find.text('Gagal memuat data.'), findsOneWidget);\n    });\n\n    testWidgets('03. Menampilkan pesan saat pengumuman tidak ditemukan', (tester) async {\n      when(mockEventOpSupabase.ambilBerdasarkanId(any)).thenAnswer((_) async => null);\n\n      await pumpWidget(tester);\n      await tester.pumpAndSettle();\n\n      expect(find.text('Pengumuman tidak ditemukan.'), findsOneWidget);\n    });\n\n    testWidgets('04. Menampilkan detail pengumuman dengan benar', (tester) async {\n      when(mockEventOpSupabase.ambilBerdasarkanId(any)).thenAnswer((_) async => event);\n\n      await pumpWidget(tester);\n      await tester.pumpAndSettle();\n\n      expect(find.text('Detail Pengumuman'), findsOneWidget);\n      expect(find.text('Aktif'), findsOneWidget);\n      expect(find.text(event.id), findsOneWidget);\n      expect(find.byType(Image), findsOneWidget);\n    });\n  });\n}\n